let audioContext=null,noiseBuffer=null;function audioStart(){if(!audioContext){audioContext=new AudioContext();noiseBuffer=audioContext.createBuffer(1,audioContext.sampleRate*.25,audioContext.sampleRate);const a=noiseBuffer.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=Math.random()*2-1;}audioContext.resume();}
