function normalizeServer(value){let u;try{u=new URL(value.trim());}catch{throw Error('Enter your multiplayer server address first.');}if(!['http:','https:'].includes(u.protocol))throw Error('Use an http:// or https:// server address.');if(location.protocol==='https:'&&u.protocol!=='https:'&&!['localhost','127.0.0.1'].includes(u.hostname))throw Error('An online game needs an HTTPS server address.');return u.origin;}
let joinTimeout;async function play(){if(joining||!view)return;audioStart();$('menu-error').textContent='';joining=true;$('play').disabled=true;try{isPractice=tab==='practice';save('ss-name',nameInput.value);const join={type:'join',create:tab==='create',code:$('room-code').value,name:nameInput.value,settings:{...DEFAULTS,map:selectedMap,mode:selectedMode},loadout,bots:+$('bots').value,team:+$('team').value};if(isPractice){transport=new Worker('./practice-worker.js',{type:'module'});transport.onmessage=e=>receive(e.data);transport.onerror=()=>failConnection('Practice could not start. Reload the page and try again.');transport.postMessage(join);}else{const server=normalizeServer($('server-url').value);save('ss-server',server);const u=new URL(server);u.protocol=u.protocol==='https:'?'wss:':'ws:';u.pathname='/play';transport=new WebSocket(u);transport.onopen=()=>message(join);transport.onmessage=e=>{try{receive(JSON.parse(e.data));}catch{}};transport.onerror=()=>failConnection('Could not connect. Check the server address and that hosting is running. A sleeping free server can take about a minute to wake.');transport.onclose=e=>{if(connected||joining)failConnection(e.code===4001?'You were removed by the admin.':'Connection closed. Your room may have ended or the server restarted.');};}joinTimeout=setTimeout(()=>{if(joining)failConnection('Connection timed out. Open the server address once to wake it, then try again.');},75000);}catch(e){failConnection(e.message);}}
