function leave(showToast=true){clearTimeout(joinTimeout);const old=transport;transport=null;connected=false;joining=false;selfId=null;state=null;local=null;keys.clear();firing=false;scope=false;if(old instanceof Worker)old.terminate();else if(old){old.onclose=null;old.close();}if(document.pointerLockElement)document.exitPointerLock();$('damage-messages').replaceChildren();$('headshot-notice').hidden=true;clearTimeout(headshotTimer);$('menu').hidden=false;$('hud').hidden=true;$('pause').hidden=true;$('scoreboard').hidden=true;$('play').disabled=false;document.body.classList.remove('playing');view?.clear();view?.setMap(selectedMap);if(showToast)toast('You left the match.');}
