function renderScoreboard(){if(!state)return;$('scoreboard-mode').textContent=MODES[state.settings.mode].name+' / '+MAPS[state.settings.map].name.toUpperCase();$('scoreboard-title').textContent=state.ended?'MATCH COMPLETE':'LIVE STANDINGS';$('score-rows').replaceChildren();for(const p of [...state.players].sort((a,b)=>b.kills-a.kills)){const tr=document.createElement('tr');if(p.id===selfId)tr.className='self';for(const v of [p.name+(p.bot?' [BOT]':''),p.team===1?'Task Force':p.team===2?'Insurgents':'Solo',p.kills,p.assists,p.deaths]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('score-rows').append(tr);}}
function drawRadar(){if(!state||!local)return;const c=$('radar').getContext('2d'),sz=210,scale=3.6;c.clearRect(0,0,sz,sz);c.fillStyle='#13232be8';c.fillRect(0,0,sz,sz);c.strokeStyle='#a6b7bc';c.lineWidth=1;c.fillStyle='#75858a';for(const b of MAPS[state.settings.map].boxes)c.fillRect(sz/2+b.x*scale-b.w/2*scale,sz/2+b.z*scale-b.d/2*scale,b.w*scale,b.d*scale);for(const p of state.players){if(p.hp<=0)continue;if(p.id!==selfId&&(!local.team||p.team!==local.team))continue;c.fillStyle=p.id===selfId?'#b6ef53':'#a1c9ee';c.beginPath();c.arc(sz/2+p.x*scale,sz/2+p.z*scale,3.5,0,Math.PI*2);c.fill();}c.save();c.translate(sz/2+local.x*scale,sz/2+local.z*scale);c.rotate(-aim.yaw);c.strokeStyle='#b6ef53';c.beginPath();c.moveTo(-5,-10);c.lineTo(0,-17);c.lineTo(5,-10);c.stroke();c.restore();}
function updateHud(){if(!state||!local)return;$('hp').textContent=Math.ceil(local.hp);$('armor').textContent=Math.ceil(local.armor);$('weapon-name').textContent=W[local.weapon].name;const a=local.inventory[local.weapon];$('ammo').textContent=W[local.weapon].mag?a?.ammo??0:'—';$('reserve').textContent=W[local.weapon].mag?a?.reserve??0:'—';const remaining=Math.ceil(state.remaining);$('timer').textContent=Math.floor(remaining/60)+':'+String(remaining%60).padStart(2,'0');$('match-mode').textContent=MODES[state.settings.mode].name;$('target').textContent='FIRST TO '+state.settings.scoreLimit;$('map-hud').textContent=MAPS[state.settings.map].name.toUpperCase();$('score-strip').replaceChildren();for(const s of state.scores.slice(0,6)){const div=document.createElement('div');div.className='score-chip'+(s.id===selfId||s.id===local.team?' self':'');div.textContent=s.score;div.title=s.name;$('score-strip').append(div);}$('network').textContent=isPractice?'LOCAL PRACTICE':`${ping} MS · ${state.players.length}/${MODES[state.settings.mode].limit} PLAYERS`;$('scope').hidden=!scope||!W[local.weapon].scope||local.hp<=0;$('crosshair').hidden=scope||local.hp<=0;const isReload=local.reloadEnd>state.time;$('reload-bar').style.opacity=isReload?1:0;$('reload-bar').firstElementChild.style.width=isReload?100*(1-(local.reloadEnd-state.time)/W[local.weapon].reload)+'%':'0';let text='';if(state.ended)text='MATCH COMPLETE';else if(local.hp<=0)text='ELIMINATED<br>Respawning in '+Math.max(1,Math.ceil(local.respawnAt-state.time));else if(local.protectedUntil>state.time)text='SPAWN PROTECTION';else if(isReload)text='RELOADING';else if(state.players.length<MODES[state.settings.mode].limit&&!isPractice)text='WAITING FOR PLAYERS · '+state.players.length+'/'+MODES[state.settings.mode].limit;else if(state.drops.some(d=>Math.hypot(d.x-local.x,d.z-local.z)<2))text=keyLabel(bindings.use)+' · PICK UP WEAPON';$('status-center').innerHTML=text;if(!$('scoreboard').hidden)renderScoreboard();drawRadar();}
function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;elapsed+=dt;if(connected&&local&&state){const v=input();if(local.hp>0&&!state.ended){movePlayer(local,v,state.settings,dt);local.scope=scope;const speed=Math.hypot(local.vx,local.vz);if(mouseEnabled&&speed>2&&!v.walk&&!v.crouch&&local.y===0&&elapsed-footstepAt>.38){sound('step');footstepAt=elapsed;}}sendAcc+=dt;if(sendAcc>=1/60){sendAcc=0;message(v);}if(!isPractice&&now-lastPing>2000){lastPing=now;message({type:'ping',sent:now});}if(!isPractice&&now-lastStateAt>10000){failConnection('The server stopped responding. Rejoin when it is available.');}hudAcc+=dt;if(hudAcc>.1){hudAcc=0;updateHud();}damageAlpha*=Math.exp(-dt*4);$('damage-flash').style.opacity=damageAlpha;$('hitmarker').style.opacity=now<hitUntil?1:0;$('flash-overlay').style.opacity=Math.min(.97,Math.max(0,(flashUntil-now)/1500));}
 if(crosshair.dynamic&&local)applyCrosshair($('crosshair'),crosshair,Math.min(12,Math.hypot(local.vx,local.vz)*1.1+(view?.kick||0)*90));
 view?.render(dt,elapsed,local,state,selfId,aim,local&&state&&local.reloadEnd>state.time);requestAnimationFrame(frame);}requestAnimationFrame(frame);
// Server-side admin authentication; tokens exist only in this tab's memory.
let adminToken='',adminOrigin='',adminRooms=[];
$('admin-open').onclick=()=>{$('admin-server').value=$('server-url').value||location.origin;openDialog('admin-dialog');};
document.getElementById('pause-admin').onclick=document.getElementById('admin-open').onclick;async function adminRequest(method='GET',data){const response=await fetch(adminOrigin+'/api/admin'+(data?.password?'/login':''),{method,headers:{'Content-Type':'application/json',...(adminToken?{Authorization:'Bearer '+adminToken}:{})},...(data?{body:JSON.stringify(data)}:{})});const result=await response.json();if(!response.ok)throw Error(result.error||'Admin request failed');return result;}
async function refreshAdmin(){const previous=$('admin-room').value;const result=await adminRequest();adminRooms=result.rooms;$('admin-room').replaceChildren();for(const r of adminRooms)$('admin-room').add(new Option(r.code+' · '+MODES[r.settings.mode].name+' · '+r.players.length+' players',r.code));if(adminRooms.some(r=>r.code===previous))$('admin-room').value=previous;renderAdmin();}
const adminError=e=>$('admin-error').textContent=e.message;
$('admin-login').onsubmit=async e=>{e.preventDefault();$('admin-error').textContent='';try{adminOrigin=normalizeServer($('admin-server').value);const result=await adminRequest('POST',{password:$('admin-password').value});adminToken=result.token;$('admin-password').value='';$('admin-login').hidden=true;$('admin-content').hidden=false;await refreshAdmin();}catch(e){adminError(e);}};
function renderAdmin(){const r=adminRooms.find(r=>r.code===$('admin-room').value);$('admin-fields').replaceChildren();$('admin-players').replaceChildren();$('admin-form').hidden=!r;if(!r){$('admin-error').textContent='No active rooms. Host a match first, then refresh.';return;}$('admin-error').textContent='';for(const[key,label,choices]of [['mode','Match format',Object.entries(MODES).map(([k,v])=>[k,v.name])],['map','Map',Object.entries(MAPS).map(([k,v])=>[k,v.name])],['scoreLimit','Score limit'],['timeLimit','Time limit (minutes)'],['respawn','Respawn delay (seconds)'],['maxHP','Maximum health'],['armor','Starting armor'],['spawnProtection','Spawn protection (seconds)'],['moveSpeed','Movement multiplier'],['friendlyFire','Friendly fire'],['headshotsOnly','Headshots only']]){const l=document.createElement('label');l.textContent=label;const el=document.createElement(choices?'select':'input');el.name=key;if(choices)for(const [v,t]of choices)el.add(new Option(t,v));else if(typeof r.settings[key]==='boolean'){el.type='checkbox';el.checked=r.settings[key];}else{el.type='number';el.step='any';el.required=true;}el.value=r.settings[key];l.append(el);$('admin-fields').append(l);}for(const p of r.players){const row=document.createElement('div');row.className='admin-player';const name=document.createElement('span');name.textContent=p.name+' · '+(p.team===1?'Task Force':p.team===2?'Insurgents':'Solo');const b=document.createElement('button');b.textContent='Remove';b.onclick=async()=>{try{await adminRequest('POST',{code:r.code,action:'kick',playerId:p.id});await refreshAdmin();}catch(e){adminError(e);}};row.append(name,b);$('admin-players').append(row);}}
$('admin-room').onchange=renderAdmin;$('admin-refresh').onclick=()=>refreshAdmin().catch(adminError);$('admin-form').onsubmit=async e=>{e.preventDefault();const settings={};for(const el of $('admin-fields').querySelectorAll('input,select'))settings[el.name]=el.type==='checkbox'?el.checked:el.type==='number'?+el.value:el.value;try{await adminRequest('POST',{code:$('admin-room').value,action:'configure',settings});await refreshAdmin();$('admin-error').textContent='Settings applied. Match restarted.';}catch(e){adminError(e);}};$('admin-restart').onclick=async()=>{try{await adminRequest('POST',{code:$('admin-room').value,action:'restart'});$('admin-error').textContent='Match restarted.';}catch(e){adminError(e);}};$('admin-logout').onclick=()=>{adminToken='';$('admin-login').hidden=false;$('admin-content').hidden=true;};
const context=document.modelContext;if(context?.registerTool)try{context.registerTool({name:'configure_practice',title:'Configure practice',description:'Choose the map and match format on the practice setup screen. Does not start gameplay.',inputSchema:{type:'object',properties:{map:{type:'string',enum:Object.keys(MAPS)},mode:{type:'string',enum:Object.keys(MODES)}},required:['map','mode'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(connected)throw Error('Leave the current match first');if(!MAPS[input.map]||!MODES[input.mode])throw Error('Unknown map or mode');setTab('practice');selectMap(input.map);selectMode(input.mode);return{map:selectedMap,mode:selectedMode};}});}catch{}
